func:
// Deixa passar no maximo um clique por vez, e so se nenhum pulso (deste
// fluxo OU do botao do Home Assistant) tiver acontecido ha pouco.
// Cada ON no rele e' uma acao fisica real no motor.
const now = Date.now();
// Retransmissao Zigbee do MESMO aperto (o botao publica em dois topicos).
const dedupeMs = 900;
// Janela morta apos um pulso de QUALQUER origem. Espelha cooldown_s do
// script.portao_garagem_pulso no HA — mantenha os dois iguais.
const cooldownMs = 3000;
let action;

if (typeof msg.payload === 'string') {
    action = msg.payload;
} else if (msg.payload && typeof msg.payload === 'object') {
    action = msg.payload.action;
}

if (action !== 'single') {
    return null;
}

const lastAccepted = Number(flow.get('portao_garagem_last_click_ms') || 0);
if (now - lastAccepted < dedupeMs) {
    return null;
}

// Cooldown compartilhado: carimbado pelo no 'carimbar pulso' a cada ON do
// rele, inclusive os que vieram do botao do dashboard.
const lastPulse = Number(flow.get('portao_garagem_last_pulse_ms') || 0);
if (now - lastPulse < cooldownMs) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'clique ignorado (cooldown)' });
    node.warn('portao: clique ignorado — pulso ha ' + (now - lastPulse) + 'ms (cooldown ' + cooldownMs + 'ms)');
    return null;
}

flow.set('portao_garagem_last_click_ms', now);
node.status({ fill: 'green', shape: 'dot', text: 'pulso ' + new Date(now).toLocaleTimeString() });
msg.payload = {
    action,
    source_topic: msg.topic,
    received_at: new Date(now).toISOString(),
};
return msg;

// Botoeira: fecha o contato. O TS0001 nao honra on_time, entao o pulso e'
// feito por software: este no liga, o delay+no seguinte desligam.
msg.topic = 'zigbee2mqtt/rele_acionador_portao/set';
msg.payload = JSON.stringify({ state: 'ON' });
return msg;

// Fim do pulso: abre o contato.
msg.topic = 'zigbee2mqtt/rele_acionador_portao/set';
msg.payload = JSON.stringify({ state: 'OFF' });
return msg;

// Carimba o instante de qualquer pulso do rele, venha do HA, deste
// fluxo ou de um comando manual. Nao publica nada — so registra.
const samePulseMs = 500;
const now = Date.now();

// O payload pode ser 'ON' cru (o HA publica assim, via switch.turn_on)
// ou {"state":"ON"} (formato deste fluxo e do topico de estado).
let state;
if (typeof msg.payload === 'string') {
    state = msg.payload;
} else if (msg.payload && typeof msg.payload === 'object') {
    state = msg.payload.state;
}

if (String(state).toUpperCase() !== 'ON') {
    return null;
}

// O mesmo pulso chega duas vezes (comando + estado). Conta uma so.
const last = Number(flow.get('portao_garagem_last_pulse_ms') || 0);
if (now - last < samePulseMs) {
    return null;
}

flow.set('portao_garagem_last_pulse_ms', now);
node.status({ fill: 'blue', shape: 'dot', text: 'pulso ' + new Date(now).toLocaleTimeString() });
return null;

let state;

if (msg.status) {
    const statusText = String(msg.status.text || '').toLowerCase();
    if (msg.status.fill === 'red' || /disconnected|offline|error/.test(statusText)) {
        state = 'offline';
    } else {
        // Uma conexão MQTT restaurada não garante que a bridge Zigbee voltou.
        // O tópico bridge/state será responsável por marcar 'online'.
        return null;
    }
} else {
    let value = msg.payload;
    if (Buffer.isBuffer(value)) {
        value = value.toString('utf8');
    }
    if (typeof value === 'string') {
        try {
            const parsed = JSON.parse(value);
            value = parsed?.state ?? parsed;
        } catch {
            // Versões antigas do Zigbee2MQTT publicam apenas 'online'/'offline'.
        }
    }
    if (value && typeof value === 'object') {
        value = value.state;
    }
    state = String(value || '').toLowerCase();
}

if (state !== 'online' && state !== 'offline') {
    node.status({ fill: 'grey', shape: 'ring', text: 'estado Zigbee desconhecido' });
    return null;
}

flow.set('external_lighting_zigbee_state', state);
node.status({
    fill: state === 'online' ? 'green' : 'red',
    shape: state === 'online' ? 'dot' : 'ring',
    text: `Zigbee ${state}`
});
return null;

const zigbeeState = flow.get('external_lighting_zigbee_state');

if (zigbeeState === 'offline') {
    msg.zigbee_error = true;
    msg.cancel_confirmation = true;
    msg.notify_text = 'Erro na rede Zigbee. A iluminação externa não foi acionada e o comando não será repetido.';
    node.status({ fill: 'red', shape: 'ring', text: 'comando bloqueado: Zigbee offline' });
    return [null, msg];
}

node.status({});
return [msg, null];

const topics = [
    'zigbee2mqtt/lampada_varanda/set',
    'zigbee2mqtt/lampadas_garagem/set',
    'zigbee2mqtt/refletores_jardim/set'
];

return topics.map(topic => ({
    ...msg,
    topic
}));

const previousTimer = context.get('confirmationTimer');
if (previousTimer) {
    clearTimeout(previousTimer);
}

if (msg.cancel_confirmation) {
    context.set('confirmationTimer', null);
    node.status({});
    return null;
}

const timer = setTimeout(() => {
    context.set('confirmationTimer', null);
    node.status({});
    node.send(msg);
}, 5000);

context.set('confirmationTimer', timer);
node.status({ fill: 'yellow', shape: 'ring', text: 'aguardando confirmação' });
return null;

finalize:
const timer = context.get('confirmationTimer');
if (timer) {
    clearTimeout(timer);
}
context.set('confirmationTimer', null);

func:
const expected = msg.expected_state || msg.payload?.expected_state;
const labels = {
    lampada_varanda: 'varanda',
    lampadas_garagem: 'garagem',
    refletores_jardim: 'jardim'
};
const states = {
    lampada_varanda: msg.payload?.lampada_varanda,
    lampadas_garagem: msg.payload?.lampadas_garagem,
    refletores_jardim: msg.payload?.refletores_jardim
};
const networkFailureStates = new Set([undefined, null, '', 'unknown', 'unavailable']);
const unavailable = Object.entries(states)
    .filter(([, state]) => networkFailureStates.has(state))
    .map(([entity]) => labels[entity]);

if (flow.get('external_lighting_zigbee_state') === 'offline' || unavailable.length > 0) {
    msg.zigbee_error = true;
    const affected = unavailable.length > 0 ? ` Sem comunicação com: ${unavailable.join(', ')}.` : '';
    msg.notify_text = `Erro na rede Zigbee.${affected} O comando da iluminação externa não será repetido.`;
    return msg;
}

const failed = Object.entries(states)
    .filter(([, state]) => state !== expected)
    .map(([entity, state]) => `${labels[entity]} ${state}`);

if (failed.length === 0) {
    msg.notify_text = msg.notify_success || msg.notify_text;
    return msg;
}

const expectedText = expected === 'on' ? 'ligada' : 'desligada';
msg.notify_text = `Erro ao acionar a iluminação externa. Esperado: ${expectedText}. Estado atual: ${failed.join(', ')}. O comando não será repetido.`;
return msg;

// Ponto(s) de referencia geografica: vem do ambiente do container (.env ->
// `env_file` do servico nodered no docker-compose), NUNCA hardcoded aqui -
// este repositorio e publico e a coordenada de casa e' o endereco da familia.
// Sem essas variaveis o fluxo degrada DE PROPOSITO para o estado de zona do
// Home Assistant ("home"/"not_home"), que ja e' o fallback usado quando o GPS
// nao e' confiavel; nunca calcula distancia com coordenada invalida.
const HOME_LAT = Number(env.get("HOME_LAT"));
const HOME_LON = Number(env.get("HOME_LON"));
const HOME_KNOWN = Number.isFinite(HOME_LAT) && Number.isFinite(HOME_LON);
const ARM_DISTANCE_M = 100;
const MAX_GPS_ACCURACY_M = 100;

// Cadencia de refresh acelera conforme carro/pessoa se aproxima de casa.
const IPHONE_REFRESH_INTERVAL_MS = 60 * 1000;       // longe: 1 min
const IPHONE_NEAR_REFRESH_INTERVAL_MS = 30 * 1000;  // perto: 30 s
const IPHONE_NEARBY_DISTANCE_M = 2000;
const IPHONE_LAST_REFRESH_KEY = "sec_iphone_last_refresh_ts";

const KIA_REFRESH_INTERVAL_MS = 15 * 60 * 1000;     // alinhado ao piso real do coordinator
const KIA_NEAR_REFRESH_INTERVAL_MS = 15 * 60 * 1000; // aproximacao pontual usa sec_approach_wake_gate
const KIA_NEARBY_DISTANCE_M = 1500;
const KIA_LAST_REFRESH_KEY = "sec_kia_last_force_refresh_ts";
const KIA_BASELINE_INTERVAL_MS = 15 * 60 * 1000;    // em casa: respeita o piso real de wake do backend BR
const KIA_BASELINE_HOUR_START = 7;                  // baseline so' das 07h ...
const KIA_BASELINE_HOUR_FINISH = 22;                // ... as 22h (poupa a bateria 12V de madrugada)

function distanceMeters(lat1, lon1, lat2, lon2) {
    const toRad = (value) => value * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) ** 2;
    return 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function distanceFromHome(entity) {
    if (!HOME_KNOWN) return null;
    const attrs = entity?.attributes ?? {};
    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const gpsAccuracy = Number(attrs.gps_accuracy);
    const hasCoordinates = Number.isFinite(lat) && Number.isFinite(lon);
    const hasGpsAccuracy = Number.isFinite(gpsAccuracy);
    const reliableCoordinates = hasCoordinates && (!hasGpsAccuracy || gpsAccuracy <= MAX_GPS_ACCURACY_M);
    return reliableCoordinates ? Math.round(distanceMeters(HOME_LAT, HOME_LON, lat, lon)) : null;
}

function reliableCoords(entity) {
    const attrs = entity?.attributes ?? {};
    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const gpsAccuracy = Number(attrs.gps_accuracy);
    const hasCoordinates = Number.isFinite(lat) && Number.isFinite(lon);
    const hasGpsAccuracy = Number.isFinite(gpsAccuracy);
    return hasCoordinates && (!hasGpsAccuracy || gpsAccuracy <= MAX_GPS_ACCURACY_M) ? { lat, lon } : null;
}

function mergeWithIcloudFallback(primary, fallback) {
    // The companion-app tracker (primary) can get stuck reporting a stale
    // "home" fix if iOS suspends background updates. The iCloud (Find My)
    // tracker polls independently, so when both have reliable coordinates,
    // trust whichever one is farther from home.
    const primaryCoords = reliableCoords(primary);
    const fallbackCoords = reliableCoords(fallback);
    if (HOME_KNOWN && primaryCoords && fallbackCoords) {
        const primaryDistance = distanceMeters(HOME_LAT, HOME_LON, primaryCoords.lat, primaryCoords.lon);
        const fallbackDistance = distanceMeters(HOME_LAT, HOME_LON, fallbackCoords.lat, fallbackCoords.lon);
        return fallbackDistance > primaryDistance ? fallback : primary;
    }
    if (primaryCoords) return primary;
    if (fallbackCoords) return fallback;
    if (primary?.state === "home" && fallback?.state === "not_home") return fallback;
    return primary;
}

function isAway(entity) {
    const distance = distanceFromHome(entity);
    if (distance !== null) {
        return distance > ARM_DISTANCE_M;
    }
    return entity?.state === "not_home";
}

const gabriel = mergeWithIcloudFallback(msg.payload?.gabriel, msg.payload?.gabriel_icloud);
const valeria = mergeWithIcloudFallback(msg.payload?.valeria, msg.payload?.valeria_icloud);

const awayEntities = [];
for (const [name, entity] of Object.entries({
    gabriel,
    valeria,
    creta: msg.payload?.creta,
})) {
    if (isAway(entity)) {
        awayEntities.push(name);
    }
}

msg.payload.refresh_allowed = awayEntities.length > 0;
msg.payload.refresh_away_entities = awayEntities;

const now = Date.now();
const anyoneAway = awayEntities.length > 0;

// Cadencia dos iPhones: acelera para 30s quando a pessoa mais proxima que
// ainda esta fora chega a <= IPHONE_NEARBY_DISTANCE_M de casa. O tick base
// agora e' de 30s, entao o intervalo e' controlado por tempo (nao pelo
// periodo do inject) para nao depender da cadencia do disparo.
const personDistances = [gabriel, valeria]
    .map((entity) => distanceFromHome(entity))
    .filter((distance) => distance !== null);
const nearestPerson = personDistances.length ? Math.min(...personDistances) : null;
const personNearby = nearestPerson !== null && nearestPerson <= IPHONE_NEARBY_DISTANCE_M;
const iphoneInterval = personNearby ? IPHONE_NEAR_REFRESH_INTERVAL_MS : IPHONE_REFRESH_INTERVAL_MS;
const lastIphoneRefresh = flow.get(IPHONE_LAST_REFRESH_KEY) ?? 0;
const shouldRefreshIphones = anyoneAway && (now - lastIphoneRefresh) >= iphoneInterval;
if (shouldRefreshIphones) {
    // request_location_update nao tem rate limit conhecido, entao marcar aqui
    // (otimista) e' aceitavel: se o HA estiver fora, perde-se no maximo um
    // ciclo e o proximo tick tenta de novo.
    flow.set(IPHONE_LAST_REFRESH_KEY, now);
}

// Cadencia periodica do Creta: 15 min em qualquer distancia, igual ao piso
// BR_WAKE_MIN_INTERVAL_S do coordinator. A entrada na zone.chegando continua
// tendo um wake pontual por sec_approach_wake_gate; o tick de 30 s permanece
// apenas para a cadencia adaptativa dos iPhones.
const cretaDistance = distanceFromHome(msg.payload?.creta);
const cretaNearby = cretaDistance !== null && cretaDistance <= KIA_NEARBY_DISTANCE_M;
const cretaAway = awayEntities.includes("creta");
const lastKiaRefresh = flow.get(KIA_LAST_REFRESH_KEY) ?? 0;

// Cadencia do force-refresh do Creta:
//  - alguem fora:                  15 min (longe ou perto).
//  - entrada no anel de chegada:    wake pontual por sec_approach_wake_gate.
//  - ninguem fora (carro em casa): 15 min, so das 07h as 22h
//    (nao acorda o carro parado de madrugada; poupa a bateria 12V).
const kiaHour = new Date().getHours();
const kiaDaytime = kiaHour >= KIA_BASELINE_HOUR_START && kiaHour < KIA_BASELINE_HOUR_FINISH;
let kiaInterval;
let kiaEnabled;
if (anyoneAway) {
    kiaInterval = (cretaAway && cretaNearby) ? KIA_NEAR_REFRESH_INTERVAL_MS : KIA_REFRESH_INTERVAL_MS;
    kiaEnabled = true;
} else {
    kiaInterval = KIA_BASELINE_INTERVAL_MS;
    kiaEnabled = kiaDaytime;
}
const shouldRefreshKia = kiaEnabled && (now - lastKiaRefresh) >= kiaInterval;

// KIA_LAST_REFRESH_KEY continua sendo gravado so por sec_creta_refresh_ack,
// apos o button.press realmente ter sucesso. Marcar aqui de forma otimista
// "consumia" o cooldown mesmo com o HA inacessivel (ex.: reiniciando),
// bloqueando retries ate o proximo intervalo em vez de tentar no proximo tick.

return [
    msg,
    shouldRefreshIphones ? msg : null,
    shouldRefreshKia ? msg : null,
];

// Only reached when button.press on button.creta_force_refresh actually
// succeeded. Marking the cooldown here (instead of optimistically before
// dispatch) means a failed call - e.g. HA unreachable mid-restart - leaves
// the cooldown untouched, so the next 1-minute tick retries immediately.
flow.set("sec_kia_last_force_refresh_ts", Date.now());
return null;

// Ponto(s) de referencia geografica: vem do ambiente do container (.env ->
// `env_file` do servico nodered no docker-compose), NUNCA hardcoded aqui -
// este repositorio e publico e a coordenada de casa e' o endereco da familia.
// Sem essas variaveis o fluxo degrada DE PROPOSITO para o estado de zona do
// Home Assistant ("home"/"not_home"), que ja e' o fallback usado quando o GPS
// nao e' confiavel; nunca calcula distancia com coordenada invalida.
const HOME_LAT = Number(env.get("HOME_LAT"));
const HOME_LON = Number(env.get("HOME_LON"));
const HOME_KNOWN = Number.isFinite(HOME_LAT) && Number.isFinite(HOME_LON);
// Portao/entrada, ~168m de HOME_LAT/HOME_LON: usado para acender o
// refletor um pouco antes da chegada em casa (ver sec_detect_arriving_source).
const GATE_LAT = Number(env.get("GATE_LAT"));
const GATE_LON = Number(env.get("GATE_LON"));
const GATE_KNOWN = Number.isFinite(GATE_LAT) && Number.isFinite(GATE_LON);
const event = msg.payload?.event;

const ACTIVE_KEY = "refletor_portao_carros_active_by_arrival";
const ARMED_KEY = "refletor_portao_carros_arrival_armed_entities";
const ARM_DISTANCE_M = 100;
const ARRIVAL_DISTANCE_M = 300;
const MAX_GPS_ACCURACY_M = 100;

function distanceMeters(lat1, lon1, lat2, lon2) {
    const toRad = (value) => value * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) ** 2;
    return 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function reliableCoords(entity) {
    const attrs = entity?.attributes ?? {};
    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const gpsAccuracy = Number(attrs.gps_accuracy);
    const hasCoordinates = Number.isFinite(lat) && Number.isFinite(lon);
    const hasGpsAccuracy = Number.isFinite(gpsAccuracy);
    return hasCoordinates && (!hasGpsAccuracy || gpsAccuracy <= MAX_GPS_ACCURACY_M) ? { lat, lon } : null;
}

function mergeWithIcloudFallback(primary, fallback) {
    // Same rationale as sec_refresh_anyone_away: prefer whichever tracker
    // (companion app vs iCloud/Find My) reports the greater distance from
    // home, since a stuck companion-app fix is the common failure mode.
    const primaryCoords = reliableCoords(primary);
    const fallbackCoords = reliableCoords(fallback);
    if (HOME_KNOWN && primaryCoords && fallbackCoords) {
        const primaryDistance = distanceMeters(HOME_LAT, HOME_LON, primaryCoords.lat, primaryCoords.lon);
        const fallbackDistance = distanceMeters(HOME_LAT, HOME_LON, fallbackCoords.lat, fallbackCoords.lon);
        return fallbackDistance > primaryDistance ? fallback : primary;
    }
    if (primaryCoords) return primary;
    if (fallbackCoords) return fallback;
    if (primary?.state === "home" && fallback?.state === "not_home") return fallback;
    return primary;
}

function position(entity) {
    const attrs = entity?.attributes ?? {};
    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const gpsAccuracy = Number(attrs.gps_accuracy);
    const hasCoordinates = Number.isFinite(lat) && Number.isFinite(lon);
    const hasGpsAccuracy = Number.isFinite(gpsAccuracy);
    const reliableCoordinates = hasCoordinates && (!hasGpsAccuracy || gpsAccuracy <= MAX_GPS_ACCURACY_M);

    return {
        entity_id: entity?.entity_id,
        state: entity?.state,
        latitude: hasCoordinates ? lat : null,
        longitude: hasCoordinates ? lon : null,
        gps_accuracy: hasGpsAccuracy ? gpsAccuracy : null,
        location_reliable: reliableCoordinates,
        distance_m: (HOME_KNOWN && reliableCoordinates) ? Math.round(distanceMeters(HOME_LAT, HOME_LON, lat, lon)) : null,
        gate_distance_m: (GATE_KNOWN && reliableCoordinates) ? Math.round(distanceMeters(GATE_LAT, GATE_LON, lat, lon)) : null,
    };
}

// "Ja em casa AGORA" segundo o tracker em tempo real (mobile_app para as
// pessoas; o unico tracker do Creta): dentro de ARM_DISTANCE_M do ponto HOME.
// NAO usa o ponto do portao nem o raio de chegada de 300m de proposito - e'
// o sinal de que a entidade ja esta em casa, nao apenas se aproximando.
function isHomePrimary(entity) {
    const attrs = entity?.attributes ?? {};
    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const gpsAccuracy = Number(attrs.gps_accuracy);
    const hasCoordinates = Number.isFinite(lat) && Number.isFinite(lon);
    const hasGpsAccuracy = Number.isFinite(gpsAccuracy);
    const reliableCoordinates = hasCoordinates && (!hasGpsAccuracy || gpsAccuracy <= MAX_GPS_ACCURACY_M);
    if (HOME_KNOWN && reliableCoordinates) {
        return distanceMeters(HOME_LAT, HOME_LON, lat, lon) <= ARM_DISTANCE_M;
    }
    if (hasGpsAccuracy && gpsAccuracy > MAX_GPS_ACCURACY_M) {
        return false;
    }
    return entity?.state === "home";
}

function homeForMs(entity) {
    const changedAt = Date.parse(entity?.last_changed ?? "");
    return Number.isFinite(changedAt) ? Date.now() - changedAt : null;
}

function isHome(item) {
    if (item.distance_m !== null) {
        return item.distance_m <= ARRIVAL_DISTANCE_M;
    }
    if (item.gps_accuracy !== null && item.gps_accuracy > MAX_GPS_ACCURACY_M) {
        return false;
    }
    return item.state === "home";
}

const gabriel = position(mergeWithIcloudFallback(msg.payload?.gabriel, msg.payload?.gabriel_icloud));
const valeria = position(mergeWithIcloudFallback(msg.payload?.valeria, msg.payload?.valeria_icloud));
const creta = position(msg.payload?.creta);

// primary_home usa SO o tracker em tempo real (nao o merge com iCloud). Serve
// para nunca acender o refletor quando a pessoa/carro ja esta em casa e o
// tracker secundario (iCloud) so agora esta "alcancando" o estado real com
// atraso - ver sec_detect_arriving_source.
gabriel.primary_home = isHomePrimary(msg.payload?.gabriel);
valeria.primary_home = isHomePrimary(msg.payload?.valeria);
creta.primary_home = isHomePrimary(msg.payload?.creta);

// Ha quanto tempo o tracker em tempo real esta no estado atual. E' o que
// separa "chegou agora" de "esta em casa ha um tempao e o tracker
// secundario (iCloud) so agora alcancou" - ver sec_detect_arriving_source.
// null quando last_changed nao vier: la o tratamento e' fail-open (acende),
// porque o modo de falha caro e' a luz NAO acender na chegada.
// Corroboracao entre os DOIS trackers da pessoa. Se QUALQUER um deles diz
// "em casa", ela nao esta se aproximando - nao ha como chegar de onde ja se
// esta. Serve contra tracker CONGELADO: em 07/08/2026 o mobile_app da Valeria
// passou 2 dias inteiros reportando a MESMA posicao (644 m) enquanto o iCloud
// mostrava 25-40 m (casa, correto). Como 644 m cai dentro do anel de 1500 m,
// a reavaliacao de zona gerou um not_home -> chegando que, a noite, teria
// acendido o refletor e disparado o push "Valeria esta chegando".
gabriel.any_tracker_home = isHomePrimary(msg.payload?.gabriel) || isHomePrimary(msg.payload?.gabriel_icloud);
valeria.any_tracker_home = isHomePrimary(msg.payload?.valeria) || isHomePrimary(msg.payload?.valeria_icloud);
creta.any_tracker_home = isHomePrimary(msg.payload?.creta);

gabriel.primary_home_for_ms = homeForMs(msg.payload?.gabriel);
valeria.primary_home_for_ms = homeForMs(msg.payload?.valeria);
creta.primary_home_for_ms = homeForMs(msg.payload?.creta);

const sunBelow = msg.payload?.sun?.state === "below_horizon";
const engineOn = msg.payload?.creta_engine?.state === "on";
const lockState = msg.payload?.creta_lock?.state;
const cretaUnlocked = lockState === "unlocked";

// ---- Trava "Creta em uso" -------------------------------------------------
// O refletor so pode acender com o Creta ligado, mas binary_sensor.creta_engine
// so ganha dado novo quando algum refresh acorda o carro (ver
// docs/CRETA_KIA_UVO_INTEGRATION.md): em 5 dias ele registrou ZERO transicoes,
// incluindo uma viagem comprovada. Exigir engine=="on" ao vivo no instante da
// travessia do anel deixaria o refletor sem acender quase sempre.
//
// Entao o gate usa um estado TRAVADO: liga em "em uso" quando o motor e visto
// ligado, e so solta quando ha evidencia real de fim de uso. Enquanto o carro
// roda longe de casa (dado velho, travado pelo proprio Kia), a trava se mantem.
const CRETA_IN_USE_KEY = "creta_in_use";
let cretaInUse = flow.get(CRETA_IN_USE_KEY) === true;
if (engineOn) {
    cretaInUse = true;
}
// Solta so com o motor desligado E (porta destravada = alguem saiu, OU carro
// em casa = viagem terminou). A ordem importa: na SAIDA o carro esta em casa
// mas com o motor ligado, e nesse caso a trava tem que permanecer.
if (!engineOn && (cretaUnlocked || isHomePrimary(msg.payload?.creta))) {
    cretaInUse = false;
}
flow.set(CRETA_IN_USE_KEY, cretaInUse);

msg.payload = {
    event,
    source: msg.payload?.source,
    // Transicao de zona da entidade que disparou. E' o que permite acender
    // ANTES da chegada (entrada na zone.chegando) e distinguir chegada de
    // saida - ver sec_detect_arriving_source.
    trigger_entity: msg.payload?.trigger_entity,
    trigger_state: msg.payload?.trigger_state,
    trigger_prev_state: msg.payload?.trigger_prev_state,
    reason: msg.payload?.reason,
    sun_below_horizon: sunBelow,
    gabriel,
    valeria,
    creta,
    creta_home: isHome(creta),
    creta_engine_on: engineOn,
    creta_lock: lockState,
    creta_unlocked: cretaUnlocked,
    creta_in_use: cretaInUse,
    active: flow.get(ACTIVE_KEY) === true,
    armed: flow.get(ARMED_KEY) ?? {},
    arriving: [],
};

if (event === "turn_off") {
    return [msg, null, null];
}
if (event === "context_update") {
    return [null, msg, null];
}
if (event === "location_update") {
    return [null, null, msg];
}
return [null, null, null];

const ACTIVE_KEY = "refletor_portao_carros_active_by_arrival";
const ARMED_KEY = "refletor_portao_carros_arrival_armed_entities";
const ACTIVATED_AT_KEY = "refletor_activated_at";
const SUPPRESS_KEY = "refletor_suppressed_until";

// Janela de silencio pos-desligamento. Sem ela, o proximo evento de
// localizacao logo apos o desligamento reacenderia o refletor - exatamente o
// "religar logo depois de apagar" que o usuario pediu para evitar.
const RELIGHT_SUPPRESSION_MS = 5 * 60 * 1000;

const active = msg.payload?.active ?? flow.get(ACTIVE_KEY) === true;

if (!active) {
    return null;
}

flow.set(ACTIVE_KEY, false);
flow.set(ARMED_KEY, {});
flow.set(ACTIVATED_AT_KEY, null);
flow.set(SUPPRESS_KEY, Date.now() + RELIGHT_SUPPRESSION_MS);
return msg;

const ARMED_KEY = "refletor_portao_carros_arrival_armed_entities";
const ARM_DISTANCE_M = 100;
const MAX_GPS_ACCURACY_M = 100;

function isAway(item) {
    if (item && item.distance_m !== null) {
        return item.distance_m > ARM_DISTANCE_M;
    }
    return item?.state === "not_home";
}

// "Em casa" para efeito de LIMPAR o armado usa o mesmo limiar de 100 m do
// armar (nao os 300 m do raio de chegada), de proposito: com 300 m havia
// sobreposicao (100-300 m armava e limpava no mesmo passo, resultado liquido
// = desarmado), e um context_update com a pessoa se aproximando nessa faixa
// apagava o armado antes da deteccao de chegada disparar. Assim armar (>100 m)
// e limpar (<=100 m) sao complementares, sem zona morta. A decisao de "Creta
// em casa" que desliga o refletor continua usando 300 m em
// sec_prepare_arrival_context (creta_home), independente disto.
function isHome(item) {
    if (item && item.distance_m !== null) {
        return item.distance_m <= ARM_DISTANCE_M;
    }
    if (item?.gps_accuracy !== null && item?.gps_accuracy > MAX_GPS_ACCURACY_M) {
        return false;
    }
    return item?.state === "home";
}

function updateAwayArming(armed, people) {
    for (const [name, item] of Object.entries(people)) {
        if (isAway(item)) {
            armed[name] = true;
        }
    }
}

function clearCurrentHomeArming(armed, people) {
    for (const [name, item] of Object.entries(people)) {
        if (isHome(item)) {
            armed[name] = false;
        }
    }
}

const armedEntities = msg.payload.armed ?? {};
const trackedPeople = {
    gabriel: msg.payload.gabriel,
    valeria: msg.payload.valeria,
    creta: msg.payload.creta,
};

updateAwayArming(armedEntities, trackedPeople);
clearCurrentHomeArming(armedEntities, trackedPeople);
flow.set(ARMED_KEY, armedEntities);

return null;

const ARMED_KEY = "refletor_portao_carros_arrival_armed_entities";
const VALERIA_APPROACH_NOTIFY_KEY = "valeria_approaching_gabriel_notified";
const VALERIA_AWAY_CYCLE_KEY = "valeria_approaching_confirmed_away_cycle";
const ARM_DISTANCE_M = 100;
const VALERIA_APPROACH_RESET_DISTANCE_M = 1000;
// "De carro": o Creta tambem precisa estar chegando junto (estava fora/armado
// e agora aparece a <= esta distancia de casa). Usa a POSICAO do Creta, nao o
// binary_sensor.creta_engine - o polling do kia_uvo quase nunca pega o motor
// "on" (ver docs/CRETA_KIA_UVO_INTEGRATION.md). Limiar mais folgado que o da
// Valeria para tolerar o lag de GPS da integracao Kia.
const CRETA_ARRIVING_DISTANCE_M = 1500;

function isAway(item) {
    if (item && item.distance_m !== null) {
        return item.distance_m > ARM_DISTANCE_M;
    }
    return item?.state === "not_home";
}

const armedEntities = msg.payload.armed ?? {};
for (const [name, item] of Object.entries({
    gabriel: msg.payload.gabriel,
    valeria: msg.payload.valeria,
    creta: msg.payload.creta,
})) {
    if (isAway(item)) {
        armedEntities[name] = true;
    }
}

msg.payload.armed = armedEntities;
flow.set(ARMED_KEY, armedEntities);

const valeria = msg.payload.valeria;
const creta = msg.payload.creta;
let notify = null;

// Aviso "Valeria chegando" (push para Gabriel).
//
// ANTES nao funcionava NUNCA: exigia valeria.distance_m entre 50 e 700 m, e
// leitura nessa faixa nao existe - o iOS so reporta travessia de zona, e ate
// 07/08/2026 a unica zona era a home (100 m). Media no recorder: 0 pontos na
// faixa em 2 dias. Exigia ainda o Creta a <=1000 m (nuvem Kia, que fica dias
// sem atualizar), somando um segundo jeito de nunca disparar.
//
// AGORA dispara na travessia do anel zone.chegando, o mesmo sinal do
// pre-acendimento do refletor. O Creta virou METADADO (muda so o texto), nao
// condicao - senao a falta de dado da Kia voltaria a engolir o aviso.
const APPROACH_ZONE = "chegando";
const triggerState = msg.payload.trigger_state;
const triggerPrevState = msg.payload.trigger_prev_state;
const isValeriaEvent = msg.payload.source === "valeria";

// O tracker secundario pode ficar congelado em home durante uma viagem. Nesse
// caso, a sequencia de SAIDA vista pelo tracker que disparou (home -> chegando
// -> not_home) e evidencia mais nova do que o home velho do outro tracker.
// Guardar o ciclo de ausencia permite aceitar a volta real sem reabrir o falso
// positivo de 07/08/2026: naquela ocasiao houve apenas uma reclassificacao
// not_home -> chegando de uma coordenada congelada, sem uma saida observada.
if (
    isValeriaEvent &&
    triggerState === "not_home" &&
    (triggerPrevState === APPROACH_ZONE || triggerPrevState === "home")
) {
    flow.set(VALERIA_AWAY_CYCLE_KEY, true);
}
const confirmedAwayCycle = flow.get(VALERIA_AWAY_CYCLE_KEY) === true;

const approachEntry =
    triggerState === APPROACH_ZONE &&
    triggerPrevState !== APPROACH_ZONE &&
    triggerPrevState !== "home" &&
    (valeria?.any_tracker_home !== true || confirmedAwayCycle);

// Rearma o aviso quando ela sai do anel (ou, como reserva, se aparecer bem
// longe), para o proximo retorno avisar de novo.
if (
    triggerState === "not_home" ||
    (valeria?.distance_m !== null && valeria.distance_m > VALERIA_APPROACH_RESET_DISTANCE_M)
) {
    flow.set(VALERIA_APPROACH_NOTIFY_KEY, false);
}
if (isValeriaEvent && triggerState === "home") {
    flow.set(VALERIA_AWAY_CYCLE_KEY, false);
}

if (
    isValeriaEvent &&
    approachEntry &&
    flow.get(VALERIA_APPROACH_NOTIFY_KEY) !== true
) {
    flow.set(VALERIA_APPROACH_NOTIFY_KEY, true);

    // "de carro" so quando ha evidencia positiva: Creta estava fora (armado)
    // e aparece perto junto com ela.
    const byCar =
        armedEntities.creta === true &&
        creta?.distance_m !== null &&
        creta.distance_m <= CRETA_ARRIVING_DISTANCE_M;

    notify = {
        payload: {
            message: byCar
                ? "Valéria está chegando de carro."
                : "Valéria está chegando.",
            by_car: byCar,
            valeria_distance_m: valeria?.distance_m ?? null,
            creta_distance_m: creta?.distance_m ?? null,
        },
    };
}

return [msg, notify];

const ARMED_KEY = "refletor_portao_carros_arrival_armed_entities";
const ARRIVAL_DISTANCE_M = 300;
const MAX_GPS_ACCURACY_M = 100;

function isHome(item) {
    // Ponto do portao/entrada conta como chegada tambem: fica mais perto da
    // rota de acesso do que HOME_LAT/HOME_LON e acende o refletor um pouco
    // antes de chegar em casa de fato.
    if (item && item.gate_distance_m !== null && item.gate_distance_m <= ARRIVAL_DISTANCE_M) {
        return true;
    }
    if (item && item.distance_m !== null) {
        return item.distance_m <= ARRIVAL_DISTANCE_M;
    }
    if (item?.gps_accuracy !== null && item?.gps_accuracy > MAX_GPS_ACCURACY_M) {
        return false;
    }
    return item?.state === "home";
}

// Anel de aproximacao (zone.chegando, raio 1500 m - ver
// homeassistant/packages/zonas_presenca.yaml). Entrar nele e' o gatilho de
// PRE-ACENDIMENTO: da ~2-3 min de antecedencia, que e' o requisito do
// usuario. O raio nao esta hardcoded aqui de proposito - so o nome da zona.
const APPROACH_ZONE = "chegando";
const triggerState = msg.payload.trigger_state;
const triggerPrevState = msg.payload.trigger_prev_state;

const trackedPeople = {
    gabriel: msg.payload.gabriel,
    valeria: msg.payload.valeria,
    creta: msg.payload.creta,
};
const source = msg.payload.source;
const sourcePosition = trackedPeople[source];
const armedEntities = msg.payload.armed ?? {};

// Entrada no anel vindo de FORA. Sair de casa tambem cruza o anel
// (home -> chegando), por isso o estado anterior importa.
//
// any_tracker_home barra tracker congelado: se o outro tracker da pessoa diz
// que ela esta em casa, isto nao e aproximacao (ver sec_prepare_arrival_context).
const approachEntry =
    triggerState === APPROACH_ZONE &&
    triggerPrevState !== APPROACH_ZONE &&
    triggerPrevState !== "home" &&
    sourcePosition?.any_tracker_home !== true;

// SAIDA de casa nunca e' chegada. A travessia home -> (chegando|not_home)
// acontece a ~100 m, dentro do raio de 300 m do isHome() abaixo, e sem este
// corte o refletor acenderia toda vez que alguem SAI no escuro. Mantem o
// armado (a pessoa esta indo embora) e nao dispara.
if (triggerPrevState === "home") {
    flow.set(ARMED_KEY, armedEntities);
    return null;
}

if (!sourcePosition || (!approachEntry && !isHome(sourcePosition))) {
    flow.set(ARMED_KEY, armedEntities);
    return null;
}

// Anti-"catch-up" do tracker secundario: quando o iCloud so agora alcanca o
// estado real de quem ja esta em casa ha um tempao, isto nao e' chegada nova.
//
// ATENCAO - este guard ja foi absoluto ("primary_home === true -> return null")
// e nisso matou 100% das chegadas: os trackers NUNCA reportam na faixa de
// 100-300 m (verificado no recorder, 2 dias, 0 pontos na faixa para os tres
// trackers; o Creta pulou de 486 m para 32 m numa leitura so). Ou seja, a
// unica leitura que existe dentro do raio de chegada ja e' com primary_home
// true - era exatamente o evento que fazia o refletor acender.
//
// Agora o corte e' por TEMPO: so descarta se o tracker em tempo real ja
// estava em casa ha mais que a carencia. Chegada de verdade cai em segundos
// (acende); catch-up do iCloud chega bem depois (o iCloud so faz poll a cada
// ~30 min, ver docs/ILUMINACAO_SEGURANCA_NODERED.md) e e' descartado.
const PRIMARY_HOME_GRACE_MS = 10 * 60 * 1000;
const homeForMs = sourcePosition.primary_home_for_ms;

if (
    !approachEntry &&
    sourcePosition.primary_home === true &&
    typeof homeForMs === "number" &&
    homeForMs > PRIMARY_HOME_GRACE_MS
) {
    armedEntities[source] = false;
    msg.payload.armed = armedEntities;
    flow.set(ARMED_KEY, armedEntities);
    return null;
}

if (armedEntities[source]) {
    msg.payload.arriving = [source];
    msg.payload.arrival_source_type = source === "creta" ? "creta" : "person";
    // "approach" = pre-acendimento (entrou no anel); "home" = rede de
    // seguranca, ja chegou (usada quando a travessia do anel nao ocorreu,
    // p.ex. quem estava parado dentro dele).
    msg.payload.arrival_stage = approachEntry ? "approach" : "home";
}
// O pre-acendimento NAO consome o armado. Se a pessoa parar dentro do anel
// (mercado a 1 km) e o backstop de 15 min apagar o refletor antes dela
// chegar, nao havera nova travessia da borda - e' a entrada na zone.home que
// precisa reacender, e para isso ela tem que continuar armada. Quem
// desarma no fim e o proprio sec_update_arming_context, quando ela chega a
// <=100 m de casa.
if (!approachEntry) {
    armedEntities[source] = false;
}
msg.payload.armed = armedEntities;
flow.set(ARMED_KEY, armedEntities);

return msg.payload.arriving.length > 0 ? msg : null;

// Same arrival event as sec_check_dark/sec_notify_valeria_approaching, but
// only lets Creta arrivals through - this is the trigger to refresh the
// day-trip-log sensor (a completed trip is exactly what just happened).
// Deliberately NOT tied to the 1-5min location refresh cadence: /tripinfo
// is a separate API call, only worth making once per actual arrival.
return msg.payload?.arrival_source_type === "creta" ? msg : null;

// GATE OBRIGATORIO: o refletor so acende se o Creta estiver em uso.
// Proximidade de pessoa sozinha NAO acende - foi pedido explicito do usuario.
// A trava creta_in_use e mantida em sec_prepare_arrival_context; ela existe
// porque binary_sensor.creta_engine fica velho entre refreshes (ver la).
const SUPPRESS_KEY = "refletor_suppressed_until";

if (msg.payload?.creta_in_use !== true) {
    return null;
}

// Anti-religamento: depois de qualquer desligamento, uma janela de silencio
// impede que o proximo evento de aproximacao reacenda o refletor em seguida.
const suppressedUntil = flow.get(SUPPRESS_KEY) ?? 0;
if (Date.now() < suppressedUntil) {
    return null;
}

msg.payload.creta_gate = msg.payload.creta_engine_on === true
    ? "engine_on"
    : "creta_in_use_latched";
return msg;

const ACTIVE_KEY = "refletor_portao_carros_active_by_arrival";
const ACTIVATED_AT_KEY = "refletor_activated_at";

flow.set(ACTIVE_KEY, true);
flow.set(ACTIVATED_AT_KEY, Date.now());
msg.payload.reason = "creta_arriving_after_dark";
return msg;

// Cada condicao abaixo e SUFICIENTE sozinha para apagar o refletor.
//
//   1. Creta desligado E destravado  -> imediato (alguem saiu do carro)
//   2. chegada do Gabriel confirmada -> apos carencia
//   3. chegada da Valeria confirmada -> apos carencia
//   4. chegada do Creta confirmada   -> apos carencia
//   5. 15 min ligado                 -> nao passa por aqui, e o backstop do
//                                       node sec_auto_off_delay
//
// CARENCIA (out1): as chegadas so apagam ~90 s depois que o refletor acendeu.
// Sem isso a luz morreria justo no trajeto carro->porta, que e o proposito
// dela: a chegada e detectada ANTES de estacionar/desligar/destravar.
const ACTIVATED_AT_KEY = "refletor_activated_at";
const ARRIVAL_OFF_GRACE_MS = 90 * 1000;

if (msg.payload?.active !== true) {
    return null;
}

// (1) fim de uso do carro: imediato.
if (msg.payload.creta_engine_on === false && msg.payload.creta_unlocked === true) {
    msg.payload.off_reason = "creta_desligado_e_destravado";
    return [msg, null];
}

// (2)(3)(4) "chegada confirmada" e a TRANSICAO para a zone.home da entidade que
// disparou o evento - nao o estado "esta em casa". Usar o estado quebraria:
// o tracker do app da Valeria passou 2 dias congelado com o iCloud dela
// marcando casa, o que deixaria a condicao permanentemente verdadeira e
// apagaria o refletor 90 s depois de cada acendimento.
const arrived =
    msg.payload.trigger_state === "home" &&
    msg.payload.trigger_prev_state !== undefined &&
    msg.payload.trigger_prev_state !== "home";

if (!arrived) {
    return null;
}

msg.payload.off_reason = `chegada_confirmada_${msg.payload.source ?? "?"}`;

const activatedAt = flow.get(ACTIVATED_AT_KEY);
const elapsed = typeof activatedAt === "number" ? Date.now() - activatedAt : ARRIVAL_OFF_GRACE_MS;
msg.delay = Math.max(0, ARRIVAL_OFF_GRACE_MS - elapsed);
return [null, msg];

// Na travessia do anel, pede um refresh real ao carro para que o gate de
// "Creta em uso" decida com o dado mais fresco possivel. Reutiliza o node
// sec_force_refresh_creta que ja existe (e o cooldown de 15 min do
// coordinator protege contra excesso - ver docs/CRETA_KIA_UVO_INTEGRATION.md).
// So na aproximacao: e um evento raro, algumas vezes por dia.
if (msg.payload?.arrival_stage !== "approach") {
    return null;
}
return msg;

const getState = (value) => {
    if (value === undefined || value === null) return undefined;
    if (typeof value === "string") return value;
    if (typeof value === "object" && value.state !== undefined) return value.state;
    return undefined;
};

// "unknown"/"unavailable" sao glitches momentaneos da integracao moni_mobile
// (falha de parsing no protocolo TCP) e nao devem contar como estado real,
// nem entrar no historico usado para detectar mudanca.
const isUnknown = (state) =>
    state === undefined ||
    state === null ||
    state === "" ||
    state === "unknown" ||
    state === "unavailable";

const data = msg.data?.event ?? msg.data ?? {};

const oldStateRaw =
    getState(data.old_state) ??
    getState(msg.old_state);

const newState =
    getState(data.new_state) ??
    getState(msg.new_state) ??
    getState(msg.payload);

const entityId =
    data.entity_id ??
    msg.topic ??
    "alarm_control_panel.alarme_moni_mobile";

const cacheKey = `last_alarm_state:${entityId}`;

if (!newState) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "sem estado novo"
    });
    return null;
}

if (isUnknown(newState)) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: `ignorado: ${newState}`
    });
    return null;
}

// Se o old_state vindo do evento for "unknown", usa o ultimo estado real
// salvo no flow context em vez de tratar o glitch como estado anterior.
const lastState = !isUnknown(oldStateRaw) ? oldStateRaw : flow.get(cacheKey);

flow.set(cacheKey, newState);

if (lastState === newState) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: `bloqueado: ${lastState} -> ${newState}`
    });
    return null;
}

msg.previous_alarm_state = lastState ?? "desconhecido";
msg.current_alarm_state = newState;
msg.alarm_state_changed = true;

node.status({
    fill: "green",
    shape: "dot",
    text: `${lastState ?? "?"} -> ${newState}`
});

return msg;

const attempt = Number(msg.arm_alarm_retry_count || 0) + 1;
msg.arm_alarm_retry_count = attempt;
const errorMessage = msg.error?.message || msg.error?.source?.name || 'erro desconhecido';

node.status({ fill: "yellow", shape: "dot", text: `tentativa ${attempt}: ${errorMessage}` });
node.warn(`Erro ao armar o alarme (tentativa ${attempt}): ${errorMessage}. Nova tentativa em instantes.`);

// Avisa no primeiro erro e depois a cada 5 tentativas para nao spammar o Alexa
// enquanto o dispositivo moni_mobile estiver offline.
if (attempt === 1 || attempt % 5 === 0) {
    msg.notify_text = attempt === 1
        ? 'Não foi possível armar o alarme: dispositivo offline. Tentando novamente...'
        : `Ainda tentando armar o alarme (tentativa ${attempt}). Dispositivo continua offline.`;
    return [msg, msg];
}
return [msg, null];

const attempt = Number(msg.disarm_alarm_retry_count || 0) + 1;
msg.disarm_alarm_retry_count = attempt;
const errorMessage = msg.error?.message || msg.error?.source?.name || 'erro desconhecido';

node.status({ fill: "yellow", shape: "dot", text: `tentativa ${attempt}: ${errorMessage}` });
node.warn(`Erro ao desarmar o alarme (tentativa ${attempt}): ${errorMessage}. Nova tentativa em instantes.`);

// Avisa no primeiro erro e depois a cada 5 tentativas para nao spammar o Alexa
// enquanto o dispositivo moni_mobile estiver offline.
if (attempt === 1 || attempt % 5 === 0) {
    msg.notify_text = attempt === 1
        ? 'Não foi possível desarmar o alarme: dispositivo offline. Tentando novamente...'
        : `Ainda tentando desarmar o alarme (tentativa ${attempt}). Dispositivo continua offline.`;
    return [msg, msg];
}
return [msg, null];

const desired = flow.get("alarm_desired");
// Aborta a tentativa de armar se o comando mais recente ja foi desarmar,
// evitando que um loop de retry (device offline) re-arme por cima de um
// desarme bem-sucedido feito nesse meio tempo.
if (desired !== "arm") {
    node.status({ fill: "blue", shape: "ring", text: `retry armar cancelado (desejado: ${desired || "?"})` });
    node.warn("Retry de ARMAR cancelado: comando mais recente foi desarmar.");
    return null;
}
return msg;

const desired = flow.get("alarm_desired");
// Espelho de alarm_guard_arm: aborta o retry de desarmar se o comando
// mais recente ja foi armar.
if (desired !== "disarm") {
    node.status({ fill: "blue", shape: "ring", text: `retry desarmar cancelado (desejado: ${desired || "?"})` });
    node.warn("Retry de DESARMAR cancelado: comando mais recente foi armar.");
    return null;
}
return msg;

const allowedSources = new Set(["gabriel", "valeria", "creta"]);
const allowedStages = new Set(["approach", "home"]);
const source = msg.payload?.source;
const arriving = msg.payload?.arriving;
const stage = msg.payload?.arrival_stage;

// Defesa em profundidade: o link recebe somente a saida positiva do detector,
// mas ainda exige a lista de chegada, a origem conhecida e o estagio valido.
if (
    !allowedSources.has(source) ||
    !allowedStages.has(stage) ||
    !Array.isArray(arriving) ||
    !arriving.includes(source)
) {
    node.status({ fill: "grey", shape: "ring", text: "evento ignorado" });
